/// Weekday name. 1970-01-01 was a THURSDAY, which is where the +4 comes from.
pub(crate) fn weekday_of(at_ms: i64) -> Option<String> {
    if at_ms <= 0 {
        return None;
    }
    const NAMES: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    let days = at_ms / 86_400_000;
    Some(NAMES[((days + 4) % 7) as usize].to_string())
}
